#!/bin/sh
# Writes Sources/NeuronSearchLab/SDKVersion.swift from VERSION. Run it after
# bumping VERSION; VersionTests fails while the two disagree.
set -eu
root="$(cd "$(dirname "$0")/.." && pwd)"
version="$(tr -d '[:space:]' < "$root/VERSION")"
cat > "$root/Sources/NeuronSearchLab/SDKVersion.swift" <<SWIFT
// Generated by scripts/sync-version.sh from VERSION. Do not edit.

extension NeuronSDK {
  /// This SDK's version, from the repository's VERSION file.
  public static let version = "$version"
}
SWIFT
echo "SDKVersion.swift -> $version"
